node -e "
const toRad = d => d * Math.PI / 180;

// Device location (San Francisco, CA)
const lat1 = 37.7749, lon1 = -122.4194;

// Shipping address: Boston, MA 02118 (South End) approximate geocode
const lat2 = 42.3388, lon2 = -71.0726;

// Haversine formula
const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const R_km = 6371.0;
const R_mi = 3958.8;

console.log('=== Distance Calculation ===');
console.log('');
console.log('From:  Device location (37.7749°N, 122.4194°W) — San Francisco, CA');
console.log('To:    4829 Elm Ridge Way, Suite 7, Boston, MA 02118, USA (~42.3388°N, 71.0726°W)');
console.log('');
console.log('Straight-line (great-circle) distance:');
console.log('  •', (R_km * c).toFixed(1), 'km');
console.log('  •', (R_mi * c).toFixed(1), 'miles');
"
